wire [15:0] imeas_sin_freq = 1;


integer counter = 0;
real pi = 3.141592;
real fin_sin;
 
logic [15:0] filter_in_sin;
 
reg clk_in;
initial
  begin
    clk_in = 1'b0;
    forever #(1us) clk_in = !clk_in;
  end
 
// This code is generated for SIN with 16-bit -> we need to generate it to
// serial and using imeas_sin_gen_en == 1 to switch from DAT file to this
always @(*)
  fin_sin = $sin(2*pi* counter * imeas_sin_freq/(imeas_sampling_rate));
 
always @(clk_in) begin
 filter_in_sin = imeas_sin_offset + (imeas_sin_amp * fin_sin);
end
 
always @(clk_in) begin
 if ((counter >= imeas_sampling_rate / imeas_sin_freq) && (fin_sin<0))
  counter = 1;
 else
  counter = counter + 1;
end
// End of generation
logic matlab_data = 0;
wire [15:0] filter_in_design;
assign filter_in_design = !matlab_data ? filter_in_sin : filter_in;


 // Module Instances
  filter u_notch_filter
    (
    .clk(clk),
    .clk_enable(clk_enable),
    .reset(!reset),
    .scan_mode(1'b0),
    .sign_en(1'b0),
    .gain_mul(2'b00),

   .scaleconst1      (scaleconst1) ,
   .coeff_b1_section1(coeff_b1_section1) ,
   .coeff_b2_section1(coeff_b2_section1) ,
   .coeff_b3_section1(coeff_b3_section1) ,
   .coeff_a2_section1(coeff_a2_section1) ,
   .coeff_a3_section1(coeff_a3_section1) ,
   .scaleconst2      (scaleconst2) ,
   .coeff_b1_section2(coeff_b1_section2) ,
   .coeff_b2_section2(coeff_b2_section2) ,
   .coeff_b3_section2(coeff_b3_section2) ,
   .coeff_a2_section2(coeff_a2_section2) ,
   .coeff_a3_section2(coeff_a3_section2) ,
/*
   .scaleconst3      (scaleconst3) ,
   .coeff_b1_section3(coeff_b1_section3) ,
   .coeff_b2_section3(coeff_b2_section3) ,
   .coeff_b3_section3(coeff_b3_section3) ,
   .coeff_a2_section3(coeff_a2_section3) ,
   .coeff_a3_section3(coeff_a3_section3) ,
   .scaleconst4      (scaleconst4) ,
   .coeff_b1_section4(coeff_b1_section4) ,
   .coeff_b2_section4(coeff_b2_section4) ,
   .coeff_b3_section4(coeff_b3_section4) ,
   .coeff_a2_section4(coeff_a2_section4) ,
   .coeff_a3_section4(coeff_a3_section4) ,
*/

    .filter_in(filter_in_design),
    .filter_out(filter_out)
    );


 // Block Statements
  // -------------------------------------------------------------
  // Driving the test bench enable
  // -------------------------------------------------------------

  always @(reset, snkDone)
  begin
    if (reset == 1'b1)
      tb_enb <= 1'b0;
    else if (snkDone == 1'b0 )
    # (clk_period)
      tb_enb <= 1'b1;
    else begin
    # (clk_period * 2);
      tb_enb <= 1'b0;
    end
  end

  always @(posedge clk or posedge reset) // completed_msg
  begin
    if (reset) begin 
       // Nothing to reset.
    end 
    else begin 
      if (snkDone == 1) begin
        if (testFailure == 0)
              $display("**************TEST COMPLETED (PASSED)**************");
        else
              $display("**************TEST COMPLETED (FAILED)**************");
      end
    end
  end // completed_msg;

  // -------------------------------------------------------------
  // System Clock (fast clock) and reset
  // -------------------------------------------------------------

  always  // clock generation
  begin // clk_gen
    clk <= 1'b1;
    # clk_high;
    clk <= 1'b0;
    # clk_low;
    if (snkDone == 1) begin
      clk <= 1'b1;
      # clk_high;
      clk <= 1'b0;
      # clk_low;
      //$stop;
      $finish;
    end
  end  // clk_gen

  initial  // reset block
  begin // reset_gen
    reset <= 1'b1;
    # (clk_period * 2);
    @ (posedge clk);
    # (clk_hold);
    reset <= 1'b0;
  end  // reset_gen

  // -------------------------------------------------------------
  // Testbench clock enable
  // -------------------------------------------------------------

  always @ (posedge clk or posedge reset)
    begin: tb_enb_delay
      if (reset == 1'b1) begin
        tbenb_dly <= 1'b0;
      end
      else begin
        if (tb_enb == 1'b1) begin
          tbenb_dly <= tb_enb;
        end
      end
    end // tb_enb_delay

reg rdEnb_t;
  always @(snkDone, tbenb_dly)
  begin
    if (snkDone == 0)
      rdEnb <= tbenb_dly;
    else
      rdEnb <= 0;
  end
/*
  always @ (posedge clk or posedge reset)
      if (reset == 1'b1) begin
        rdEnb <= 1'b0;
      end
      else begin
          rdEnb <= rdEnb_t;
        end
*/
  // -------------------------------------------------------------
  // Read the data and transmit it to the DUT
  // -------------------------------------------------------------

  always @(posedge clk or posedge reset)
  begin
    filter_in_data_log_task(clk,reset,
                            filter_in_data_log_rdenb,filter_in_data_log_addr,
                            filter_in_data_log_done);
  end

  assign filter_in_data_log_rdenb = rdEnb;

  assign rawData_filter_in = filter_in_data_log_force[filter_in_data_log_addr];

  always @ (filter_in_data_log_rdenb, filter_in_data_log_addr, tbenb_dly)
  begin // stimuli_filter_in_data_log_filter_in
    if (tbenb_dly == 0) begin
      filter_in <= # clk_hold  16'b0;
    end
    else if (filter_in_data_log_rdenb == 1) begin
      filter_in <= # clk_hold rawData_filter_in;
    end
  end // stimuli_filter_in_data_log_filter_in

  // -------------------------------------------------------------
  // Create done signal for Input data
  // -------------------------------------------------------------

  assign srcDone = filter_in_data_log_done;


  assign delayLine_out = rdEnb;
  assign expected_ce_out =  delayLine_out & clk_enable;

  // -------------------------------------------------------------
  //  Checker: Checking the data received from the DUT.
  // -------------------------------------------------------------

  always @(posedge clk or posedge reset)
  begin
    filter_out_task(clk,reset,
                    filter_out_rdenb,filter_out_addr,
                    filter_out_done);
  end

  assign filter_out_rdenb = expected_ce_out;

  assign filter_out_ref = filter_out_expected[filter_out_addr];

  reg filter_out_rdenb_ff;
  always @ (posedge clk or posedge reset)
    if (reset == 1) begin
      filter_out_rdenb_ff <= 0;
    end 
    else begin 
      filter_out_rdenb_ff <= filter_out_rdenb;
    end

  reg filter_out_rdenb_2ff;
  always @ (posedge clk or posedge reset)
    if (reset == 1) begin
      filter_out_rdenb_2ff <= 0;
    end 
    else begin 
      filter_out_rdenb_2ff <= filter_out_rdenb_ff;
    end

  always @ (posedge clk or posedge reset) // checker_filter_out
  begin
    if (reset == 1) begin
      filter_out_testFailure <= 0;
      filter_out_errCnt <= 0;
    end 
    else begin 
      if (filter_out_rdenb_ff == 1 ) begin 
        if (((abs(filter_out - filter_out_expected[filter_out_addr-1]) > 25) !== 0 )) begin
           filter_out_errCnt <= filter_out_errCnt + 1;
           filter_out_testFailure <= 1;
                   $display("ERROR at Index: %d in filter_out at time %t : Expected '%h' Actual '%h'", 
                        filter_out_addr-1, $time, filter_out_expected[filter_out_addr-1], filter_out);
           if (filter_out_errCnt >= MAX_ERROR_COUNT) 
             $display("Warning: Number of errors for filter_out have exceeded the maximum error limit");
        end
        else
                   $display("GOOD  at Index: %d in filter_out at time %t : Expected '%h' Actual '%h'", 
                        filter_out_addr-1, $time, filter_out_expected[filter_out_addr-1], filter_out); 

      end
    end
  end // checker_filter_out

  initial
    begin
      repeat(2002) @(posedge clk);
      $display("The percentage of FAILED/PASS: %d/%d = %d percent", filter_out_errCnt, MAX_ERROR_COUNT, filter_out_errCnt*100/MAX_ERROR_COUNT);
    end

  always @ (posedge clk or posedge reset) // checkDone_1
  begin
    if (reset == 1)
      check1_Done <= 0;
    else if ((check1_Done == 0) && (filter_out_done == 1) && (filter_out_rdenb == 1))
      check1_Done <= 1;
  end

  // -------------------------------------------------------------
  // Create done and test failure signal for output data
  // -------------------------------------------------------------

  assign snkDone = check1_Done;

  assign testFailure = filter_out_testFailure;

  // -------------------------------------------------------------
  // Global clock enable
  // -------------------------------------------------------------
  always @(snkDone, tbenb_dly)
  begin
    if (snkDone == 0)
      # clk_hold clk_enable <= tbenb_dly;
    else
      # clk_hold clk_enable <= 0;
  end

 // Assignment Statements
